        } else if ((b & 0xF0) == 0xE0) {
            // Three-byte character
            if (bb.remaining() >= 2) {
                byte b2 = bb.get();
                byte b3 = bb.get();
                sb.append((char) (((b & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F)));
