        char c = str.charAt(i);
        if (c < 0x80) {
            utfLen++;
        } else if (c < 0x800) {
            utfLen += 2;
        } else if (Character.isSurrogate(c)) {
            utfLen += 4;
            i++; // surrogate pair
        } else {
            utfLen += 3;
        }
