    lb = ensureCapacity(utfLen, lb, session);

    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            lb.buffer[lb.offset++] = (byte) c;
        } else if (c < 0x800) {
            lb.buffer[lb.offset++] = (byte) (0xc0 | (c >> 6));
